def f(N, A, M, O):
    total_value = 0
    A.sort(key=lambda x:x[1],reverse=True)

    for i in O:
        index_num = 0
        for j in A:
            if i == j[0]:
                if total_value + j[1] > M:
                    continue
                else:
                    total_value += j[1]
                    A.pop(index_num)
                    break
            index_num += 1
    return total_value
